const $=id=>document.getElementById(id),stage=document.querySelector('.viewer-stage'),wait=$('live-wait'),video=$('premiere-video'),live=$('live-video'),badge=document.querySelector('[data-live-badge]'),sound=$('premiere-sound');
let config=null,timer=0,syncing=false;
function format(ms){const total=Math.max(0,Math.ceil(ms/1000)),h=Math.floor(total/3600),m=Math.floor(total%3600/60),s=total%60;return h?`${h} год ${String(m).padStart(2,'0')} хв`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;}
function localDate(value){return new Intl.DateTimeFormat(undefined,{dateStyle:'full',timeStyle:'short'}).format(new Date(value));}
function now(){return Date.now()+(config?.serverTime-Date.now()||0);}
function end(){clearInterval(timer);video.pause();video.hidden=true;wait.hidden=false;stage.dataset.state='ended';badge.textContent='ПРЕМ’ЄРА ЗАВЕРШЕНА';badge.classList.remove('is-live');$('live-wait-kicker').textContent='ДЯКУЄМО ЗА ПЕРЕГЛЯД';$('live-wait-title').textContent='Презентація завершилася';$('live-wait-description').textContent='Матеріали та доступні записи можна переглянути в інших розділах кімнати.';sound.hidden=true;}
function play(){const elapsed=Math.max(0,(now()-new Date(config.startsAt).getTime())/1000),duration=config.recording.duration/1000;if(duration&&elapsed>=duration)return end();wait.hidden=true;live.hidden=true;video.hidden=false;stage.dataset.state='live';badge.textContent='ПРЕМ’ЄРА';badge.classList.add('is-live');sound.hidden=false;if(!video.src)video.src=config.recording.url;syncing=true;video.currentTime=Math.min(elapsed,Math.max(0,duration-.25));syncing=false;video.play().catch(()=>{});}
function tick(){const starts=new Date(config.startsAt).getTime(),remaining=starts-now();if(remaining<=0){play();return;}stage.dataset.state='waiting';wait.hidden=false;badge.textContent='ОЧІКУВАННЯ ПРЕМ’ЄРИ';$('live-wait-kicker').textContent='ЗАПЛАНОВАНА ПРЕМ’ЄРА';$('live-wait-title').textContent='Іван Косович скоро приєднається';$('live-wait-description').textContent=`Початок ${localDate(config.startsAt)} · залишилося ${format(remaining)}`;}
async function init(){try{const response=await fetch('/api/premiere/access',{credentials:'same-origin',cache:'no-store'});if(response.status===403){document.body.classList.add('premiere-mode');stage.dataset.state='denied';badge.textContent='ДОСТУП НЕ АКТИВОВАНО';$('live-wait-kicker').textContent='ЗАКРИТА ПРЕМ’ЄРА';$('live-wait-title').textContent='Спочатку завершіть програму підготовки';$('live-wait-description').textContent='Персональний доступ до презентації надійде в Telegram після завершення всіх етапів.';return;}if(!response.ok)return;config=await response.json();if(config.mode!=='premiere')return;document.body.classList.add('premiere-mode');document.querySelector('.viewer-actions')?.setAttribute('hidden','');$('live-status').hidden=true;tick();timer=setInterval(tick,1000);}catch{}}
sound?.addEventListener('click',()=>{video.muted=!video.muted;sound.textContent=video.muted?'Увімкнути звук':'Вимкнути звук';});
video?.addEventListener('seeking',()=>{if(!config||syncing)return;const allowed=Math.max(0,(now()-new Date(config.startsAt).getTime())/1000);if(video.currentTime>allowed+2){syncing=true;video.currentTime=allowed;syncing=false;}});
video?.addEventListener('ended',end);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&config)tick();});init();
